const frag = `
#ifdef GL_ES
precision mediump float; // Define a precisão para floats como média em dispositivos que usam OpenGL ES
#endif

// Declarações de variáveis uniformes que serão passadas para o shader
uniform vec2 u_resolution; // Resolução da tela
uniform float u_time;      // Tempo atual da animação
uniform int u_frame;       // Número do quadro atual da animação
uniform vec2 u_mouse;      // Posição do mouse na tela

#define pi 3.14159          // Define o valor de pi
#define MAX_STEPS 10        // Número máximo de passos para a marcha do raio
#define MAX_DIST 2.         // Distância máxima para a marcha do raio
#define SURF_DIST 0.02      // Distância mínima da superfície para considerar um ponto como válido

// Função para criar uma matriz de rotação 2D
mat2 Rot(float a) {
    float s = sin(a), c = cos(a); // Calcula seno e cosseno do ângulo
    return mat2(c, -s, s, c);      // Retorna a matriz de rotação
}

// Função para calcular um valor usando tangente
float thc(float a, float b) {
    return tan(a * cos(b)) / tan(a); // Retorna a tangente ajustada por cos(b)
}

// Função para gerar um valor pseudoaleatório baseado em coordenadas
float h21(vec2 a) {
    return fract(sin(dot(a.xy, vec2(12.9898, 78.233))) * 43758.5453123); // Usa a função seno e a dot product para gerar valores aleatórios
}

// Funções para calcular a distância máxima em 2D e 3D
float mlength(vec2 uv) {
    return max(abs(uv.x), abs(uv.y)); // Retorna o maior valor absoluto entre os componentes x e y
}

float mlength(vec3 p) {
    return max(max(abs(p.x), abs(p.y)), abs(p.z)); // Retorna o maior valor absoluto entre os componentes x, y e z
}

// Função de paleta de cores
vec3 pal(in float t, in vec3 a, in vec3 b, in vec3 c, in vec3 d) {
    return a + b * cos(6.28318 / 1.5 * (c * t + d)); // Gera uma cor baseada em uma paleta
}

// Função que calcula a distância do objeto para um ponto 3D
float GetDist(vec3 p) {
    float sc = 5.;   // Escala para o grid
    float sc2 = 0.1; // Escala menor para uma subdivisão mais fina

    float a = atan(p.z, p.x); // Calcula o ângulo em relação ao eixo xz
    float th = atan(p.y, p.x); // Calcula o ângulo em relação ao eixo xy
    float r = length(p) - (2.00 + p.x); // Distância do ponto em relação a um centro

    // Manipula o tempo para criar uma animação fluida
    float tim = 12. * a + r * 1. - u_time;
    tim += 0.5 * h21(p.xy); // Adiciona um valor aleatório ao tempo

    // Redefine o ponto de entrada em função do tempo
    p = 0.1 * r * vec3(sin(a + tim) * cos(th + tim), cos(a - tim) * sin(th + tim), cos(th + tim) + sin(th + tim));

    // Divide o ponto em partes inteiras e fracionárias
    vec3 ip = floor(sc2 * p) + 0.5; 
    vec3 fp = fract(sc2 * p) - 0.5;

    // Calcula a cor baseada em uma variação de ângulo
    vec3 vec = 0.5 * vec3(cos(10. * h21(ip.xy) + tim), cos(10. * h21(ip.yz) + tim), cos(10. * h21(ip.zx) + tim));

    float d0 = length(p) - 4. * mlength(fp) - 0.1; // Calcula a distância para o objeto
    d0 = length(p) - 2.; // Ajusta a distância

    // Aplica uma transformação ao ponto
    p.y += cos(0.2 * r); 
    p = vec3(a / pi, p.y, -0.4 * log(r) + .1 * u_time); // Redefine p em função do ângulo e do tempo

    // Calcula posições em um grid
    vec2 ipos = floor(sc * p.xz) + 0.25;
    vec2 fpos = sin(sc * p.xz / pi / 2.) - 0.25;

    return 0.23 * d0; // Retorna a distância calculada
}

// Função que realiza a marcha do raio
float RayMarch(vec3 ro, vec3 rd) {
    float dO = 0.2; // Inicializa a distância do objeto

    for(int i = 0; i < MAX_STEPS; i++) { // Loop até o número máximo de passos
        vec3 p = ro + rd * dO; // Calcula a posição do ponto
        float dS = GetDist(p); // Obtém a distância para o ponto
        dO += dS; // Acumula a distância
        if(dO > MAX_DIST || abs(dS) < SURF_DIST) break; // Para se ultrapassar a distância máxima ou se a distância da superfície for muito pequena
    }

    return dO; // Retorna a distância total percorrida
}

// Função que calcula a normal em um ponto 3D
vec3 GetNormal(vec3 p) {
    float d = GetDist(p); // Obtém a distância para o ponto
    vec2 e = vec2(.20, 0); // Um pequeno vetor para calcular a normal

    // Calcula a normal baseada nas distâncias em direções levemente deslocadas
    vec3 n = d - vec3(
        GetDist(p - e.xyy),
        GetDist(p - e.yxy),
        GetDist(p - e.yyx));

    return normalize(n); // Retorna a normal normalizada
}

// Função para obter a direção do raio
vec3 GetRayDir(vec2 uv, vec3 p, vec3 l, float z) {
    vec3 f = normalize(l - p), // Vetor de direção
          r = normalize(cross(vec3(0, 1, 0), f)), // Vetor perpendicular
          u = cross(f, r), // Outro vetor perpendicular
          c = f * z, // Escala do vetor de direção
          i = c + uv.x * r + uv.y * u, // Combina as direções para formar a direção do raio
          d = normalize(i); // Normaliza a direção final
    return d; // Retorna a direção do raio
}

// Função para calcular a cor de fundo
vec3 Bg(vec3 rd) {
    float k = rd.y * .5 + .5; // Ajusta a componente y da direção do raio

    // Mistura duas cores baseadas na componente y da direção do raio
    vec3 col = mix(vec3(.25, 0., 0.), vec3(0.), k);
    return col; // Retorna a cor do fundo
}

void main() {
    // Normaliza as coordenadas do pixel (gl_FragCoord) para um espaço de coordenadas que vai de -0.5 a 0.5
    vec2 uv = (gl_FragCoord.xy - 1.0 / 2. * u_resolution.xy) / u_resolution.y;

    // Reduz a velocidade da animação multiplicando o tempo por 0.25
    float time = 0.15 * u_time;  // O fator de velocidade foi alterado de 0.5 para 0.25 para desacelerar mais

    // Calcula a altura do objeto usando uma função cosseno
    float height = .5 + cos(time);

    // Aumenta a distância do objeto para torná-lo maior na cena
    float dist = 3.5; // Aumenta o tamanho do objeto
    vec3 ro = vec3(dist * cos(time), height, dist * sin(time)); // Define a posição do "ray origin" (origem do raio)

    // Obtém a direção do raio a partir das coordenadas do pixel, posição do objeto e altura
    vec3 rd = GetRayDir(uv, ro, vec3(0, height, 0), 1.); 
    vec3 col = vec3(0); // Inicializa a cor como preto (0, 0, 0)

    // Realiza a marcha do raio para encontrar a distância até a superfície
    float d = RayMarch(ro, rd);

    // Se a distância for menor que a distância máxima, calcular a cor do pixel
    if(d < MAX_DIST) {
        // Calcula a posição do ponto na superfície
        vec3 p = ro - rd * d;

        // Obtém a normal na superfície do ponto
        vec3 n = GetNormal(p);

        // Calcula o vetor refletido e refratado com base na normal
        vec3 r = reflect(rd, n);
        vec3 rf = refract(rd, n, 0.1);

        // Calcula a iluminação difusa
        float dif = dot(n, normalize(vec3(1, 1, 1))) * 0.5 + 0.5;
        col = 0.05 * vec3(dif); // A cor é afetada pela iluminação difusa

        // Define uma cor base que varia com o tempo
        float b = 0.25 + 0.25 * cos(u_time);

        // Calcula ângulos para o vetor de refração
        float a = atan(rf.z, rf.x);
        float c = atan(rf.z, rf.y);

        // Determina a posição do pixel em uma grade
        vec2 ipos = floor(p.xz) + 0.5;
        float h = mix(h21(ipos), 0., 0.5 + 0.5 * cos(u_time));

        // Ajusta a cor com base no vetor de refração e no tempo
        col.r -= 1.15 + 0.25 * sin(10. * rf.y + u_time - 0.25 * pi);
        col.g += 0.15 + 0.25 * cos(10. * rf.y + u_time);
        col.b += 0.15 + 0.25 * cos(10. * rf.y + u_time + 0.5 * pi);

        // Adiciona um efeito visual baseado em um truque de cor
        col += thc(2., 2.5 * length(p) - u_time);

        // Aplica um gradiente de cores ao objeto
        vec3 e = vec3(1.); // Cor de base
        col = col * pal(1.5 * length(p) - u_time, e, e, e, 0.25 * vec3(0., 0.33, 0.66));

        // Ajusta a cor final baseada na normal
        col *= n.x / 2.;
    }

    // Aplica uma correção gama à cor final
    col = pow(col, vec3(0.5545));

    // Define a cor final do pixel
    gl_FragColor = vec4(col, 1.0); // Define a cor e a opacidade do pixel
}
`

// === Tab: vert ===
const vert = `
// vert file and comments from adam ferriss
// https://github.com/aferriss/p5jsShaderExamples

// our vertex data
attribute vec3 aPosition;

// our texcoordinates
attribute vec2 aTexCoord;

void main() {

  // copy the position data into a vec4, using 1.0 as the w component
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

  // send the vertex information on to the fragment shader
  gl_Position = positionVec4;
}
`;

